const SlideLogic = {
 order:(actual,expected)=>actual.length===expected.length&&actual.every((v,i)=>v===expected[i]),
 selection:(actual,expected)=>actual.length===expected.length&&expected.every(v=>actual.includes(v)),
 number:(actual,expected)=>String(actual).trim()!==''&&Number.isFinite(Number(actual))&&Math.abs(Number(actual)-expected)<1e-6,
 color:reading=>reading==='white'?'move':reading==='red'?'delivery':'check'
};
if(typeof module!=='undefined')module.exports=SlideLogic;
const LessonPlayer = (()=>{
 const memory=new Map(),names=['Mission','Explore','My guess','Try it','Build','Check','What I learned'];let id=1,host;
 const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function fresh(i){const p=LESSON_SLIDES[i-1].practice;return{page:0,explore:0,prediction:null,exit:null,order:p.items?.map((_,j)=>j)||[],selected:[],value:'',checked:false,passed:false,feedback:'',sensor:{reading:'white',seen:[],last:''},build:[],reflection:''};}
 function data(){return memory.get(id);}
 function quiz(q,key){const a=data()[key];return `<p class="slide-question">${q.q}</p><div class="slide-options">${q.options.map((v,i)=>`<button class="slide-option ${a===i?'chosen':''}" data-choice="${key}:${i}" aria-pressed="${a===i}"><span>${String.fromCharCode(65+i)}</span>${v}</button>`).join('')}</div><div class="slide-feedback ${a!==null?(a===q.correct?'correct':'retry'):''}" role="status">${a===null?'Choose an answer to see feedback.':e(q.feedback[a])}</div>`;}
 function practice(p){const s=data();let content='';
  if(p.type==='order')content=`<ol class="slide-order">${s.order.map((v,i)=>`<li><b>${i+1}</b><span>${p.items[v]}</span><button class="mini" data-order="${i}:-1" aria-label="Move ${e(p.items[v])} up" ${i===0?'disabled':''}>↑</button><button class="mini" data-order="${i}:1" aria-label="Move ${e(p.items[v])} down" ${i===s.order.length-1?'disabled':''}>↓</button></li>`).join('')}</ol>`;
  if(p.type==='select')content=`<div class="slide-options">${p.items.map((v,i)=>`<label class="slide-option"><input type="checkbox" data-select="${i}" ${s.selected.includes(i)?'checked':''}>${v}</label>`).join('')}</div>`;
  if(p.type==='number')content=`${p.rows?'<div class="scroll"><table><thead><tr><th>Test</th><th>Parcel stayed on</th><th>In space</th><th>Hit nothing</th></tr></thead><tbody>'+p.rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':''}<label for="slide-number">Your answer (${p.unit})</label><input id="slide-number" type="number" step="any" value="${e(s.value)}"><details><summary>Show a hint</summary><p>${p.hint}</p></details>`;
  if(p.type==='color')return `<p class="slide-question">${p.q}</p><div class="color-lab"><div class="color-swatch ${s.sensor.reading}" aria-hidden="true"></div><div><label for="sensor-color">Color the sensor reads</label><select id="sensor-color">${['white','red','unknown'].map(c=>`<option value="${c}" ${s.sensor.reading===c?'selected':''}>${c.toUpperCase()}</option>`).join('')}</select><button class="btn primary" id="sensor-observe">Test this reading</button></div></div><div class="slide-feedback" role="status">${s.sensor.last||'Choose a color. What do you think will happen?'}</div><div class="sensor-cases">${['white','red','unknown'].map(c=>`<span class="${s.sensor.seen.includes(c)?'seen':''}">${s.sensor.seen.includes(c)?'✓':'○'} ${c}</span>`).join('')}</div><p class="small">This shows one choice. In a real test, the robot stays stopped after red or unknown until you start a new test.</p>${s.passed?'<p class="slide-feedback correct">You tried all three colors. '+p.why+'</p>':''}`;
  return `<p class="slide-question">${p.q}</p>${content}<button class="btn primary" id="check-practice">Check my work</button><div class="slide-feedback ${s.checked?(s.passed?'correct':'retry'):''}" role="status">${s.checked?s.feedback:'Try it, then check your answer. You can change it and try again.'}</div>`;
 }
 function render(focus=false){const s=data(),l=COURSE.lessons[id-1],d=LESSON_SLIDES[id-1];let body='';
  if(s.page===0)body=`<div class="slide-split"><div><p class="eyebrow">YOUR MISSION</p><h3>${l.mission}</h3><p>${l.objective}</p><p class="small">Move through seven slides, then test the real build with your teacher.</p><audio controls preload="none" src="audio/lesson-${id}.wav?v=chipper-20260910"></audio><details><summary>Read the audio words</summary><p>${l.narration}</p></details></div><img src="images/mission-${id}.png?v=module-art-1" alt="${VISUALS[id-1][2]}"></div>`;
  if(s.page===1)body=`<div class="slide-split"><img src="images/mission-${id}.png?v=module-art-1" alt="${VISUALS[id-1][2]}"><div><p class="slide-question">Select each idea to explore it.</p><div class="explore-tabs">${d.explore.map(([title],i)=>`<button class="btn ${s.explore===i?'primary':''}" data-explore="${i}" aria-pressed="${s.explore===i}">${title}</button>`).join('')}</div><div class="explore-detail" role="status"><h3>${d.explore[s.explore][0]}</h3><p>${d.explore[s.explore][1]}</p></div><p class="small">This picture shows an idea. Use LEGO’s instructions to build the real robot.</p></div></div>`;
  if(s.page===1)body+=`<aside class="word-help"><h3>Words to know</h3><dl class="word-list">${l.words.map(([term,meaning])=>`<div><dt>${e(term)}</dt><dd>${e(meaning)}</dd></div>`).join('')}</dl></aside>`;
  if(s.page===2)body=quiz(d.prediction,'prediction');
  if(s.page===3)body=practice(d.practice);
  if(s.page===4)body=`<p class="slide-question">${l.mission}</p>${id===8?buildChoicesHTML():''}<p><strong>Gather:</strong> ${l.parts}</p><div class="build-steps">${l.build.map((t,i)=>`<label><input type="checkbox" data-build="${i}" ${s.build.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="slide-feedback"><strong>What counts as success?</strong> ${l.success}</div><div class="actions"><a class="btn primary" href="workbooks/module-${l.id}.pdf" target="_blank">Module workbook</a><a class="btn" href="programs/lesson-${id}.html" target="_blank">Coding guide</a><a class="btn" href="workbooks/index.html" target="_blank">Print by class</a><button class="btn" id="slide-open-lab">Open simulator</button></div><p class="small">Check each step after you do it. Correct quiz answers do not mean your real robot has passed its tests.</p>`;
  if(s.page===5)body=quiz(d.exit,'exit');
  if(s.page===6){const checks=[s.prediction===d.prediction.correct,s.passed,s.exit===d.exit.correct];body=`<p class="slide-question">What did your tests show?</p><div class="slide-results">${['Prediction','Practice activity','Exit check'].map((name,i)=>`<button data-review="${[2,3,5][i]}" class="${checks[i]?'passed':''}">${checks[i]?'✓':'○'} ${name}<small>${checks[i]?'Correct / explored':'Return and try it'}</small></button>`).join('')}</div><label for="slide-reflection">One thing I learned, a result from my test, and what I will try next:</label><textarea id="slide-reflection" rows="4" placeholder="In my test… I learned… Next I will try…">${e(s.reflection)}</textarea><div class="actions"><button class="btn primary" id="slide-download">Download my lesson notes</button>${id<8?'<button class="btn" id="slide-next-lesson">Go to the next lesson →</button>':''}</div><p class="small">${checks.filter(Boolean).length} of 3 screen activities finished. Building steps: ${s.build.length} of ${l.build.length} steps you checked. Notes stay in this open page; download them before refreshing or closing.</p>`;}
  host.innerHTML=`<div class="player-top"><div><span class="eyebrow">INTERACTIVE LESSON</span><h3 id="slide-heading" tabindex="-1">${names[s.page]} <span>· ${s.page+1} / 7</span></h3></div><button class="btn" id="slide-expand" aria-pressed="${host.classList.contains('expanded')}">${host.classList.contains('expanded')?'Normal size':'Bigger slides'}</button></div><nav class="slide-dots" aria-label="Lesson slides">${names.map((n,i)=>`<button data-page="${i}" aria-label="Slide ${i+1}: ${e(n)}" title="${e(n)}" ${s.page===i?'aria-current="step"':''}>${i+1}<span>${n}</span></button>`).join('')}</nav><div class="slide-body">${body}</div><div class="player-bottom"><button class="btn" id="slide-back" ${s.page===0?'disabled':''}>← Back</button><p>Lesson ${id} · ${l.title}</p><button class="btn primary" id="slide-next" ${s.page===6?'disabled':''}>Next →</button></div>`;
  host.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(+b.dataset.page));host.querySelector('#slide-back').onclick=()=>go(s.page-1);host.querySelector('#slide-next').onclick=()=>go(s.page+1);
  host.querySelector('#slide-expand').onclick=()=>{host.classList.toggle('expanded');document.body.classList.toggle('slide-focus',host.classList.contains('expanded'));render();host.querySelector('#slide-expand').focus();};
  host.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>{s.explore=+b.dataset.explore;render();host.querySelector(`[data-explore="${s.explore}"]`).focus();});
  host.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const [key,n]=b.dataset.choice.split(':');s[key]=+n;render();host.querySelector(`[data-choice="${key}:${n}"]`).focus();});
  host.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{const [i,delta]=b.dataset.order.split(':').map(Number),j=i+delta;[s.order[i],s.order[j]]=[s.order[j],s.order[i]];s.checked=false;s.passed=false;render();host.querySelector(`[data-order="${j}:${-delta}"]`).focus();});
  host.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{const v=+c.dataset.select;s.selected=c.checked?[...s.selected,v]:s.selected.filter(n=>n!==v);s.checked=false;s.passed=false;const f=host.querySelector('.slide-feedback');f.textContent='You changed your choices. Check your answer again.';f.className='slide-feedback';});
  if(host.querySelector('#slide-number'))host.querySelector('#slide-number').oninput=ev=>{s.value=ev.target.value;s.checked=false;s.passed=false;host.querySelector('.slide-feedback').textContent='Answer changed. Check your work again.';host.querySelector('.slide-feedback').className='slide-feedback';};
  if(host.querySelector('#check-practice'))host.querySelector('#check-practice').onclick=()=>{const p=d.practice;s.passed=p.type==='order'?SlideLogic.order(s.order,p.correct):p.type==='select'?SlideLogic.selection(s.selected,p.correct):SlideLogic.number(s.value,p.value);s.checked=true;s.feedback=s.passed?'Correct. '+p.why:p.type==='order'?'Not yet. Read where to start and where to finish. Try a different order.':p.type==='select'?'Not yet. Choose two safe ideas that leave wheels, sensor and Stop controls clear.':'Not yet. Use the hint and try the number again.';render();host.querySelector('#check-practice').focus();};
  if(host.querySelector('#sensor-color'))host.querySelector('#sensor-color').onchange=ev=>{s.sensor.reading=ev.target.value;render();host.querySelector('#sensor-color').focus();};
  if(host.querySelector('#sensor-observe'))host.querySelector('#sensor-observe').onclick=()=>{const r=s.sensor.reading,c=SlideLogic.color(r);if(!s.sensor.seen.includes(r))s.sensor.seen.push(r);s.sensor.last=c==='move'?'WHITE: move slowly for 0.1 seconds, then stop and read again.':c==='delivery'?'RED: stop. The delivery test is over. Stay stopped.':'UNKNOWN: stop. End the test and check the setup.';s.passed=s.sensor.seen.length===3;render();host.querySelector('#sensor-observe').focus();};
  host.querySelectorAll('[data-build]').forEach(c=>c.onchange=()=>{const n=+c.dataset.build;s.build=c.checked?[...s.build,n]:s.build.filter(v=>v!==n);});
  if(host.querySelector('#slide-open-lab'))host.querySelector('#slide-open-lab').onclick=()=>{host.classList.remove('expanded');document.body.classList.remove('slide-focus');showView('lab');};
  host.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>go(+b.dataset.review));
  if(host.querySelector('#slide-reflection'))host.querySelector('#slide-reflection').oninput=ev=>s.reflection=ev.target.value;
  if(host.querySelector('#slide-download'))host.querySelector('#slide-download').onclick=()=>download(`mission-${id}-lesson-notes.txt`,`${l.title}\n\nWhat I will learn: ${l.objective}\n\nPrediction: ${s.prediction===null?'Not answered':d.prediction.options[s.prediction]}\nPractice completed correctly: ${s.passed?'Yes':'Not yet'}\nExit check: ${s.exit===null?'Not answered':d.exit.options[s.exit]}\nBuilding steps I checked: ${s.build.length}/${l.build.length}\n\nWhat I learned:\n${s.reflection||'No notes written yet.'}\n\nScreen activities cannot check how the real robot works.`);
  if(host.querySelector('#slide-next-lesson'))host.querySelector('#slide-next-lesson').onclick=()=>{document.body.classList.remove('slide-focus');renderLesson(id+1);document.querySelector('#slide-heading').focus();};
  if(focus)host.querySelector('#slide-heading').focus();
 }
 function go(n){if(n<0||n>6)return;data().page=n;render(true);}
 function mount(element,lesson){document.body.classList.remove('slide-focus');host=element;id=lesson;if(!memory.has(id))memory.set(id,fresh(id));render();host.onkeydown=ev=>{if(ev.key==='Tab'&&host.classList.contains('expanded')){const f=[...host.querySelectorAll('button:not([disabled]),a[href],input,textarea,summary,audio[controls]')].filter(el=>el.offsetParent!==null);if(f.length&&ev.shiftKey&&document.activeElement===f[0]){ev.preventDefault();f[f.length-1].focus();}else if(f.length&&!ev.shiftKey&&document.activeElement===f[f.length-1]){ev.preventDefault();f[0].focus();}}if(ev.key==='Escape'&&host.classList.contains('expanded')){host.classList.remove('expanded');document.body.classList.remove('slide-focus');render(true);}};}
 return {mount};
})();
